// Event definitions
interface OrderEvent {
  eventId: string;
  timestamp: Date;
  orderId: string;
  version: number;
}

interface OrderCreatedEvent extends OrderEvent {
  type: 'OrderCreated';
  customerId: string;
  items: OrderItem[];
  totalAmount: number;
}

interface OrderValidatedEvent extends OrderEvent {
  type: 'OrderValidated';
  validationStatus: 'valid' | 'invalid';
  validationErrors?: string[];
}

// Event publisher
class OrderService {
  async createOrder(orderData: CreateOrderRequest): Promise<Order> {
    const order = await this.repository.save(orderData);

    // Publish event
    await this.eventPublisher.publish<OrderCreatedEvent>({
      type: 'OrderCreated',
      eventId: generateId(),
      timestamp: new Date(),
      orderId: order.id,
      version: 1,
      customerId: order.customerId,
      items: order.items,
      totalAmount: order.totalAmount
    });

    return order;
  }
}

// Event subscriber
class InventoryService {
  @EventHandler('OrderCreated')
  async handleOrderCreated(event: OrderCreatedEvent): Promise<void> {
    // Reserve inventory for order items
    await this.reserveInventory(event.items);
  }
}

// Command model
interface ProductCommand {
  id: string;
  name: string;
  price: number;
  stock: number;
  lastModified: Date;
}

// Query model
interface ProductQuery {
  id: string;
  name: string;
  price: number;
  available: boolean;
  category: string;
  averageRating: number;
}

// Command handler
class ProductCommandHandler {
  async updatePrice(command: UpdateProductPriceCommand): Promise<void> {
    const product = await this.productRepository.findById(command.productId);
    if (!product) {
      throw new ProductNotFoundError(command.productId);
    }

    product.price = command.newPrice;
    product.lastModified = new Date();
    await this.productRepository.save(product);

    // Publish event to update read model
    await this.eventPublisher.publish(new ProductPriceUpdatedEvent(
      product.id, 
      command.newPrice
    ));
  }
}

// Query handler
class ProductQueryHandler {
  async getProductDetails(query: GetProductQuery): Promise<ProductQuery> {
    return await this.productReadModel.findById(query.productId);
  }

  async searchProducts(criteria: SearchProductsQuery): Promise<ProductQuery[]> {
    return await this.productReadModel.search(criteria);
  }
}

import express from 'express';
import { createProxyMiddleware } from 'http-proxy-middleware';

const app = express();

// Authentication middleware
app.use('/api', authenticateToken);

// Rate limiting
app.use('/api', rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
}));

// Service routing
app.use('/api/users', createProxyMiddleware({
  target: 'http://user-service:3001',
  changeOrigin: true,
  pathRewrite: {
    '^/api/users': ''
  }
}));

app.use('/api/orders', createProxyMiddleware({
  target: 'http://order-service:3002',
  changeOrigin: true,
  pathRewrite: {
    '^/api/orders': ''
  }
}));

app.use('/api/products', createProxyMiddleware({
  target: 'http://product-service:3003',
  changeOrigin: true,
  pathRewrite: {
    '^/api/products': ''
  }
}));

// Request/response transformation
app.use('/api', (req, res, next) => {
  // Add correlation ID
  req.headers['x-correlation-id'] = req.headers['x-correlation-id'] || generateId();

  // Log request
  console.log(`[${req.headers['x-correlation-id']}] ${req.method} ${req.path}`);

  next();
});

class ShardedUserRepository {
  private shards: Map<string, DatabaseConnection>;
  private shardCount: number;

  constructor(shardCount: number) {
    this.shardCount = shardCount;
    this.initializeShards();
  }

  private getShardKey(userId: string): string {
    const hash = this.hashUserId(userId);
    return `shard_${hash % this.shardCount}`;
  }

  async findById(userId: string): Promise<User | null> {
    const shardKey = this.getShardKey(userId);
    const shard = this.shards.get(shardKey);

    return await shard.collection('users').findOne({ userId });
  }

  async save(user: User): Promise<void> {
    const shardKey = this.getShardKey(user.userId);
    const shard = this.shards.get(shardKey);

    await shard.collection('users').updateOne(
      { userId: user.userId },
      { $set: user },
      { upsert: true }
    );
  }

  // Read operations can use replica shards
  async findByEmail(email: string): Promise<User | null> {
    // Query all shards in parallel for read operations
    const queries = Array.from(this.shards.values()).map(shard =>
      shard.collection('users').findOne({ email })
    );

    const results = await Promise.all(queries);
    return results.find(result => result !== null) || null;
  }
}

import amqp from 'amqplib';

class OrderMessageQueue {
  private connection: Connection;
  private channel: Channel;

  async initialize(): Promise<void> {
    this.connection = await amqp.connect(process.env.RABBITMQ_URL);
    this.channel = await this.connection.createChannel();

    // Declare queues
    await this.channel.assertQueue('order.created', { durable: true });
    await this.channel.assertQueue('order.processed', { durable: true });
    await this.channel.assertQueue('order.failed', { durable: true });
  }

  async publishOrderCreated(order: Order): Promise<void> {
    const message = {
      eventId: generateId(),
      timestamp: new Date().toISOString(),
      type: 'OrderCreated',
      data: order
    };

    await this.channel.sendToQueue(
      'order.created',
      Buffer.from(JSON.stringify(message)),
      { persistent: true }
    );
  }

  async consumeOrderProcessed(): Promise<void> {
    await this.channel.consume('order.processed', async (msg) => {
      if (!msg) return;

      const event = JSON.parse(msg.content.toString());

      try {
        await this.handleOrderProcessed(event);
        this.channel.ack(msg);
      } catch (error) {
        console.error('Error processing order:', error);
        this.channel.nack(msg, false, false); // Reject and don't requeue
      }
    });
  }

  private async handleOrderProcessed(event: OrderProcessedEvent): Promise<void> {
    // Update order status in database
    await this.orderRepository.updateStatus(
      event.orderId, 
      'processed'
    );

    // Send notification to customer
    await this.notificationService.sendOrderProcessedNotification(
      event.customerId,
      event.orderId
    );
  }
}

import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';

class OAuth2Service {
  async generateTokens(user: User): Promise<TokenPair> {
    const accessToken = jwt.sign(
      { 
        sub: user.id,
        email: user.email,
        scopes: user.scopes 
      },
      process.env.JWT_ACCESS_SECRET,
      { expiresIn: '15m' }
    );

    const refreshToken = jwt.sign(
      { 
        sub: user.id,
        type: 'refresh'
      },
      process.env.JWT_REFRESH_SECRET,
      { expiresIn: '7d' }
    );

    return { accessToken, refreshToken };
  }

  async validateAccessToken(token: string): Promise<TokenPayload> {
    try {
      const payload = jwt.verify(token, process.env.JWT_ACCESS_SECRET) as TokenPayload;
      return payload;
    } catch (error) {
      throw new InvalidTokenError('Invalid access token');
    }
  }

  async refreshAccessToken(refreshToken: string): Promise<string> {
    try {
      const payload = jwt.verify(refreshToken, process.env.JWT_REFRESH_SECRET) as RefreshTokenPayload;

      if (payload.type !== 'refresh') {
        throw new InvalidTokenError('Invalid refresh token');
      }

      const user = await this.userRepository.findById(payload.sub);
      if (!user) {
        throw new UserNotFoundError('User not found');
      }

      const newAccessToken = jwt.sign(
        { 
          sub: user.id,
          email: user.email,
          scopes: user.scopes 
        },
        process.env.JWT_ACCESS_SECRET,
        { expiresIn: '15m' }
      );

      return newAccessToken;
    } catch (error) {
      throw new TokenRefreshError('Token refresh failed');
    }
  }
}

import Redis from 'ioredis';

class RateLimiter {
  private redis: Redis;

  constructor(redis: Redis) {
    this.redis = redis;
  }

  async isAllowed(
    key: string, 
    limit: number, 
    windowMs: number
  ): Promise<{ allowed: boolean; remaining: number; resetTime: number }> {
    const now = Date.now();
    const window = Math.floor(now / windowMs);
    const redisKey = `rate_limit:${key}:${window}`;

    const pipeline = this.redis.pipeline();
    pipeline.incr(redisKey);
    pipeline.expire(redisKey, Math.ceil(windowMs / 1000));

    const results = await pipeline.exec();
    const current = results[0][1] as number;

    const allowed = current <= limit;
    const remaining = Math.max(0, limit - current);
    const resetTime = (window + 1) * windowMs;

    return { allowed, remaining, resetTime };
  }

  middleware() {
    return async (req: Request, res: Response, next: NextFunction) => {
      const key = req.ip; // Or user ID, API key, etc.
      const limit = 100; // requests
      const windowMs = 15 * 60 * 1000; // 15 minutes

      const result = await this.isAllowed(key, limit, windowMs);

      res.set({
        'X-RateLimit-Limit': limit.toString(),
        'X-RateLimit-Remaining': result.remaining.toString(),
        'X-RateLimit-Reset': new Date(result.resetTime).toISOString()
      });

      if (!result.allowed) {
        return res.status(429).json({
          error: 'Too Many Requests',
          message: 'Rate limit exceeded',
          retryAfter: Math.ceil((result.resetTime - Date.now()) / 1000)
        });
      }

      next();
    };
  }
}

class CacheManager {
  private memoryCache: Map<string, CacheItem>;
  private redis: Redis;
  private memorySize: number;

  constructor(redis: Redis, memorySize: number = 1000) {
    this.redis = redis;
    this.memoryCache = new Map();
    this.memorySize = memorySize;
  }

  async get<T>(key: string): Promise<T | null> {
    // Check memory cache first
    const memoryItem = this.memoryCache.get(key);
    if (memoryItem && !this.isExpired(memoryItem)) {
      return memoryItem.value as T;
    }

    // Check Redis cache
    const redisValue = await this.redis.get(key);
    if (redisValue) {
      const item = JSON.parse(redisValue) as CacheItem<T>;

      // Update memory cache
      this.setMemoryCache(key, item);

      return item.value;
    }

    return null;
  }

  async set<T>(
    key: string, 
    value: T, 
    ttl: number = 3600
  ): Promise<void> {
    const item: CacheItem<T> = {
      value,
      timestamp: Date.now(),
      ttl
    };

    // Set in memory cache
    this.setMemoryCache(key, item);

    // Set in Redis cache
    await this.redis.setex(
      key, 
      ttl, 
      JSON.stringify(item)
    );
  }

  async invalidate(pattern: string): Promise<void> {
    // Invalidate from memory cache
    for (const [key] of this.memoryCache.entries()) {
      if (key.includes(pattern)) {
        this.memoryCache.delete(key);
      }
    }

    // Invalidate from Redis cache
    const keys = await this.redis.keys(`*${pattern}*`);
    if (keys.length > 0) {
      await this.redis.del(...keys);
    }
  }

  private setMemoryCache<T>(key: string, item: CacheItem<T>): void {
    // Evict oldest items if cache is full
    if (this.memoryCache.size >= this.memorySize) {
      const oldestKey = this.memoryCache.keys().next().value;
      this.memoryCache.delete(oldestKey);
    }

    this.memoryCache.set(key, item);
  }

  private isExpired(item: CacheItem): boolean {
    return Date.now() - item.timestamp > item.ttl * 1000;
  }
}

interface CacheItem<T = any> {
  value: T;
  timestamp: number;
  ttl: number;
}
